package hu.laci.cms.backend.dao.content;

import hu.laci.cms.backend.dao.common.BaseDao;
import hu.laci.cms.backend.model.common.QuerySpec;
import hu.laci.cms.backend.model.content.ContentItem;
import hu.laci.cms.backend.model.content.ContentItemProperty;
import hu.laci.cms.backend.model.content.ContentStatus;
import hu.laci.cms.backend.model.content.ContentType;
import hu.laci.cms.backend.model.site.Site;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** JDBC content-item persistence using the shared {@link BaseDao} mapping. */
public class ContentItemDaoImpl extends BaseDao<ContentItem, ContentItemProperty> implements ContentItemDao {
    public ContentItemDaoImpl() { super(ContentItem.class); }
    @Override public long countBySite(Site site) { return findCustomOne("countContentBySite", "SELECT COUNT(*) AS row_count FROM content_items WHERE site_id = ?", List.of(site), resultSet -> resultSet.getLong("row_count"), "Failed to count content.").orElse(0L); }
    @Override public List<ContentItem> findBySite(Site site, ContentType type, ContentStatus status, String groupCode) { QuerySpec<ContentItemProperty> query = QuerySpec.<ContentItemProperty>create().where(ContentItemProperty.SITE).equalsTo(site).orderBy(ContentItemProperty.ID.asc()); if (type != null) { query.where(ContentItemProperty.TYPE).equalsTo(type); } if (status != null) { query.where(ContentItemProperty.STATUS).equalsTo(status); } if (groupCode != null) { query.where(ContentItemProperty.GROUP_CODE).equalsTo(groupCode); } return findAll(query); }
    @Override public Optional<ContentItem> findBySiteAndId(Site site, Long id) { return findAll(QuerySpec.<ContentItemProperty>create().where(ContentItemProperty.SITE).equalsTo(site).where(ContentItemProperty.ID).equalsTo(id)).stream().findFirst(); }
    @Override public Optional<ContentItem> findBySiteTypeAndSlug(Site site, ContentType type, String slug) { return findAll(QuerySpec.<ContentItemProperty>create().where(ContentItemProperty.SITE).equalsTo(site).where(ContentItemProperty.TYPE).equalsTo(type).where(ContentItemProperty.SLUG).equalsTo(slug)).stream().findFirst(); }
    @Override public long countByFeaturedMediaId(Long mediaId) { return findCustomOne("countContentByFeaturedMedia", "SELECT COUNT(*) AS row_count FROM content_items WHERE featured_media_id = ?", List.of(mediaId), resultSet -> resultSet.getLong("row_count"), "Failed to count media references.").orElse(0L); }
    @Override public void deleteTagAssignments(Long contentItemId) { executeCustomUpdate("deleteContentTags", "DELETE FROM content_item_tags WHERE content_item_id = ?", List.of(contentItemId), "Failed to delete content tags."); }
    @Override public void replaceTagAssignments(Long contentItemId, Collection<Long> tagIds) { deleteTagAssignments(contentItemId); for (Long tagId : tagIds) { executeCustomUpdate("createContentTag", "INSERT INTO content_item_tags (content_item_id, tag_id) VALUES (?, ?)", List.of(contentItemId, tagId), "Failed to assign content tag."); } }
    @Override public List<Long> findTagIds(Long contentItemId) { return findTagIdsByContentItemIds(List.of(contentItemId)).getOrDefault(contentItemId, List.of()); }
    @Override public Map<Long, List<Long>> findTagIdsByContentItemIds(Collection<Long> contentItemIds) { if (contentItemIds == null || contentItemIds.isEmpty()) { return Map.of(); } List<Long> ids = new ArrayList<>(contentItemIds); String placeholders = String.join(", ", java.util.Collections.nCopies(ids.size(), "?")); List<TagPair> pairs = findCustomList("findContentTagIds", "SELECT content_item_id, tag_id FROM content_item_tags WHERE content_item_id IN (" + placeholders + ") ORDER BY content_item_id, tag_id", ids, resultSet -> new TagPair(resultSet.getLong("content_item_id"), resultSet.getLong("tag_id")), "Failed to find content tags."); Map<Long, List<Long>> result = new LinkedHashMap<>(); for (TagPair pair : pairs) { result.computeIfAbsent(pair.contentItemId(), ignored -> new ArrayList<>()).add(pair.tagId()); } return result; }
    @Override public List<ContentItem> findPublishedPage(Site site, ContentType type, String groupCode, java.sql.Timestamp publishedBefore, int limit, int offset) { String groupClause = groupCode == null ? "" : " AND group_code = ?"; List<Object> parameters = new ArrayList<>(List.of(site, type, publishedBefore, limit, offset)); if (groupCode != null) parameters.add(3, groupCode); String projection = "content_items.id AS content_items_id, content_items.site_id AS content_items_site_id, content_items.type AS content_items_type, content_items.title AS content_items_title, content_items.slug AS content_items_slug, content_items.summary AS content_items_summary, content_items.content AS content_items_content, content_items.group_code AS content_items_group_code, content_items.status AS content_items_status, content_items.featured_media_id AS content_items_featured_media_id, content_items.published_at AS content_items_published_at, content_items.created_at AS content_items_created_at, content_items.updated_at AS content_items_updated_at, content_items.created_by AS content_items_created_by, content_items.updated_by AS content_items_updated_by"; return findCustomList("findPublishedContentPage", "SELECT " + projection + " FROM content_items WHERE site_id = ? AND type = ? AND status = 'PUBLISHED' AND published_at IS NOT NULL AND published_at <= ?" + groupClause + " ORDER BY published_at DESC, id DESC LIMIT ? OFFSET ?", parameters, this::mapEntity, "Failed to find published content."); }
    @Override public long countPublished(Site site, ContentType type, String groupCode, java.sql.Timestamp publishedBefore) { String groupClause = groupCode == null ? "" : " AND group_code = ?"; List<Object> parameters = new ArrayList<>(List.of(site, type, publishedBefore)); if (groupCode != null) parameters.add(groupCode); return findCustomOne("countPublishedContent", "SELECT COUNT(*) AS row_count FROM content_items WHERE site_id = ? AND type = ? AND status = 'PUBLISHED' AND published_at IS NOT NULL AND published_at <= ?" + groupClause, parameters, resultSet -> resultSet.getLong("row_count"), "Failed to count published content.").orElse(0L); }
    @Override public Optional<ContentItem> findPublicBySiteTypeAndSlug(Site site, ContentType type, String slug, java.sql.Timestamp publishedBefore) { String projection = "content_items.id AS content_items_id, content_items.site_id AS content_items_site_id, content_items.type AS content_items_type, content_items.title AS content_items_title, content_items.slug AS content_items_slug, content_items.summary AS content_items_summary, content_items.content AS content_items_content, content_items.group_code AS content_items_group_code, content_items.status AS content_items_status, content_items.featured_media_id AS content_items_featured_media_id, content_items.published_at AS content_items_published_at, content_items.created_at AS content_items_created_at, content_items.updated_at AS content_items_updated_at, content_items.created_by AS content_items_created_by, content_items.updated_by AS content_items_updated_by"; return findCustomList("findPublicContentBySlug", "SELECT " + projection + " FROM content_items WHERE site_id = ? AND type = ? AND slug = ? AND status = 'PUBLISHED' AND published_at IS NOT NULL AND published_at <= ?", List.of(site, type, slug, publishedBefore), this::mapEntity, "Failed to find public content.").stream().findFirst(); }
    private record TagPair(Long contentItemId, Long tagId) { }
}
